/**
 * OTP Generator — Secure OTP generation and verification.
 * Generated by BackendForge
 */

const crypto = require('crypto');
const { env } = require('../config/env');
const { OTP } = require('../models');

/**
 * Generate a 6-digit OTP.
 */
const generateOTP = () => {
  return crypto.randomInt(100000, 999999).toString();
};

/**
 * Verify an OTP for a user.
 * @param {string} userId
 * @param {string} code
 * @param {string} purpose
 * @returns {{ valid: boolean, message?: string }}
 */
const verifyOTP = async (userId, code, purpose = 'admin_login') => {
  const { Op } = require('sequelize');
  const otp = await OTP.findOne({
    where: {
      userId,
      purpose,
      verified: false,
      expiresAt: { [Op.gt]: new Date() },
    },
    order: [['createdAt', 'DESC']],
  });

  if (!otp) {
    return { valid: false, message: 'No active OTP found. Please request a new one.' };
  }

  // Check max attempts
  if (otp.attempts >= otp.maxAttempts) {
    await otp.destroy();
    return { valid: false, message: 'Maximum OTP attempts exceeded. Please request a new one.' };
  }

  // Increment attempts
  await otp.update({ attempts: otp.attempts + 1 });

  // Verify code
  if (otp.code !== code) {
    return { valid: false, message: `Invalid OTP. ${otp.maxAttempts - otp.attempts} attempts remaining.` };
  }

  // Mark as verified and clean up
  await otp.update({ verified: true });
  await OTP.destroy({ where: { userId, purpose } }); // Clean up

  return { valid: true };
};

module.exports = { generateOTP, verifyOTP };
